parameters.jsCode:
const corpus = [
  { titulo: 'Bassols', file_id: 'PEGAR_FILE_ID_BASSOLS' },
  { titulo: 'Schejtman', file_id: 'PEGAR_FILE_ID_SCHEJTMAN' },
  { titulo: 'Geblesco', file_id: 'PEGAR_FILE_ID_GEBLESCO' },
  { titulo: 'Documento 4', file_id: 'PEGAR_FILE_ID_DOC4' },
  { titulo: 'Documento 5', file_id: 'PEGAR_FILE_ID_DOC5' }
];

const documentos = corpus.map(doc => ({
  type: 'document',
  source: { type: 'file', file_id: doc.file_id },
  title: doc.titulo,
  citations: { enabled: true }
}));

const pregunta = $json.body.question;

return [{ json: { documentos, pregunta } }];

parameters.jsonBody:
={{ {
  model: "claude-sonnet-5",
  max_tokens: 4096,
  system: "Sos el Investigador de Fuentes de LACAN·LAB. Respondé EXCLUSIVAMENTE con base en los documentos adjuntos (corpus lacaniano). Si no hay evidencia para responder, decí literalmente: NO ENCONTRADO EN LAS FUENTES DISPONIBLES. Estructurá siempre la respuesta en tres partes: 1) Evidencia directa (cita textual con autor, obra y página cuando sea posible), 2) Inferencia o síntesis (marcando explícitamente que es una deducción tuya y no una cita), 3) Limitaciones (qué no se puede afirmar con las fuentes disponibles). No mezcles conceptos de distintos autores como si fueran equivalentes salvo que el corpus lo haga explícito.",
  messages: [
    {
      role: "user",
      content: [...$json.documentos, { type: "text", text: $json.pregunta }]
    }
  ]
} }}

parameters.jsCode:
const blocks = $json.content || [];
let texto = '';
const citas = [];

for (const block of blocks) {
  if (block.type === 'text') {
    texto += block.text;
    if (block.citations) {
      for (const c of block.citations) {
        citas.push({
          texto_citado: c.cited_text,
          documento: c.document_title || c.document_index
        });
      }
    }
  }
}

return [{ json: { respuesta_v1_texto: texto, citas_v1: citas } }];

parameters.jsonBody:
={{ {
  model: "claude-haiku-4-5-20251001",
  max_tokens: 2048,
  system: "Sos el Auditor de Fuentes (V2) de LACAN·LAB. Revisás la respuesta del Investigador (V1). Como V1 usa citas nativas verificadas por la API, NO necesitás chequear si las citas existen o si las páginas son correctas: eso ya está garantizado estructuralmente. Tu trabajo se concentra en un solo eje: TEORIA. Evaluá: atribución correcta de conceptos a sus autores (no mezclar Lacan con Miller, ni Freud con Schejtman salvo que el corpus lo indique), anacronismos conceptuales, acuerdos artificiales entre autores donde no los hay, y si V1 distingue claramente entre lo que la fuente dice literalmente y lo que infiere. Formato de salida: veredicto con semaforo (verde/amarillo/rojo) y un parrafo breve de justificacion. No agregues ejes de fuentes ni alucinacion.",
  messages: [
    {
      role: "user",
      content: "Pregunta original: " + $('Armar documentos (file_id)').item.json.pregunta + "\n\nRespuesta del Investigador (V1):\n" + $json.respuesta_v1_texto
    }
  ]
} }}

