const blocks = $json.content || [];
let auditoria = '';
for (const block of blocks) {
  if (block.type === 'text') auditoria += block.text;
}

return [{
  json: {
    pregunta: $('Armar documentos (file_id)').item.json.pregunta,
    respuesta_v1: $('Extraer respuesta V1').item.json.respuesta_v1_texto,
    citas_v1: $('Extraer respuesta V1').item.json.citas_v1,
    auditoria_v2: auditoria
  }
}];
